'use server';

import { updateTag } from 'next/cache';
import { createPost as createPostInDb } from '@/lib/posts';

export async function createPost(formData: FormData) {
  const title = formData.get('title') as string;
  const content = formData.get('content') as string;

  if (!title?.trim() || !content?.trim()) {
    throw new Error('Title and content are required');
  }

  await createPostInDb({ title: title.trim(), content: content.trim() });

  // Invalidate the "posts" cache tag. updateTag ensures the next request
  // waits for fresh data (no stale content served) - unlike revalidateTag
  // which uses stale-while-revalidate and may serve stale data.
  updateTag('posts');
}

